g("newton-special-permits-and-variances","Zoning","ZONING RELIEF","What is the difference between a special permit and a variance in Newton?","Special Permits vs. Variances in Newton, MA",
 "Who grants special permits and variances in Newton, the two-thirds City Council vote, site plan approval, and the legal tests for a variance.",
 "The City Council grants special permits, by a two-thirds vote of all councilors, together with site plan approval. Variances are heard by the Zoning Board of Appeals. A variance requires conditions such as soil, shape or topography that especially affect the property, plus substantial hardship.",
 ["ord"],
 [("Special permits",[F("The City Council grants special permits by a two-thirds vote of all the Council (Sec. 7.3.3.A).","ord"),F("A special-permit application requires concurrent site plan approval (Sec. 7.3.1.A).","ord"),
   F("Findings include an appropriate site, no adverse effect on the neighborhood, and no nuisance or serious vehicle or pedestrian hazard (Sec. 7.3.3.C).","ord"),
   F("Examples include increased FAR and a third story for detached houses (Sec. 3.1.9.A.2, 3.2.11.A.2).","ord")]),
  ("Variances",[F("Variance applications are heard by the Zoning Board of Appeals (Sec. 7.6.1.A).","ord"),
   F("The property must have soil, shape or topography conditions that especially affect it, rather than the district generally (Sec. 7.6.1.B).","ord"),
   F("Literal enforcement must cause substantial hardship (Sec. 7.6.1.C).","ord"),F("Relief must not substantially harm the public good or undermine the ordinance's intent (Sec. 7.6.1.D).","ord")])],
 [Q("Who approves special permits in Newton?","The City Council, by a two-thirds vote of all councilors (Sec. 7.3.3.A).","ord"),
  Q("Who hears variances?","The Zoning Board of Appeals (Sec. 7.6.1.A).","ord"),
  Q("Can I get a special permit to build a larger house?","The ordinance lists increased FAR as something a special permit may allow (Sec. 3.1.9.A.2).","ord"),
  Q("What do I need to show for a variance?","Conditions of soil, shape or topography that especially affect the property, substantial hardship, and no substantial detriment to the public good (Sec. 7.6.1).","ord")],
 ["Whether your project needs relief at all.","Application forms, fees and timelines."],"planning",
 ["newton-floor-area-ratio-far","newton-building-height-limits","building-permit-vs-zoning-approval"])

g("are-adus-allowed-in-massachusetts","ADUs","ADUs","Are ADUs allowed in Massachusetts?","Are ADUs Allowed in Massachusetts? The 2024 Law Explained",
 "Massachusetts' 2024 Affordable Homes Act protects one accessory dwelling unit on single-family lots. What the law (M.G.L. c.40A §3) and state guidance say.",
 "Yes. Since February 2, 2025, state law has protected one accessory dwelling unit (ADU) in single-family residential zoning districts from being prohibited, unreasonably restricted, or held to discretionary zoning approval. Owner occupancy cannot be required. Towns may still apply reasonable rules such as setbacks and height limits.",
 ["mgl3","adu-faq"],
 [("What state law says",[F("The 2024 Affordable Homes Act amended the Zoning Act to create protected-use ADUs (760 CMR 71.01).","760cmr"),
   F("A single ADU, or renting it, in a single-family residential zoning district is protected against prohibition, unreasonable restriction, and discretionary zoning approval.","mgl3"),
   F("Owner occupancy of either dwelling cannot be required.","mgl3"),F("No more than one additional parking space may be required, and none within 0.5 miles of the listed transit facilities.","mgl3"),
   F("Reasonable regulations remain allowed, including septic rules, site plan review, setbacks, and bulk and height limits.","mgl3"),
   F("State guidance gives February 2, 2025 as the date protected-use ADUs became allowed as of right.","adu-faq"),F("State guidance says local zoning provisions that conflict with the law are unenforceable.","adu-faq")])],
 [Q("When did the Massachusetts ADU law take effect?","State guidance gives February 2, 2025 as the date protected-use ADUs became allowed as of right.","adu-faq"),
  Q("Do I have to live on the property?","No. The law says owner occupancy of either dwelling cannot be required.","mgl3"),
  Q("Can my town require parking for an ADU?","No more than one additional space, and none within 0.5 miles of the listed transit facilities.","mgl3"),
  Q("Can I rent my ADU?","The law protects the ADU and its rental. Local rules may set minimum rental terms. Newton's is 30 days.","mgl3","ord"),
  Q("Can my town still regulate ADUs?","Yes. Reasonable regulations remain allowed, such as setbacks, bulk and height limits, and site plan review.","mgl3")],
 ["How your town applies the law locally."],"adu-state",
 ["how-big-can-an-adu-be-in-massachusetts","newton-adu-rules","newton-zoning-setbacks"])

g("how-big-can-an-adu-be-in-massachusetts","ADUs","ADUs","How big can an ADU be in Massachusetts?","How Big Can an ADU Be in Massachusetts?",
 "The Massachusetts ADU size cap: half the main home's gross floor area or 900 sq ft, whichever is smaller. Plus how floor area is counted, and Newton's local limits.",
 "Under state law, a protected-use ADU can be no larger than half the gross floor area of the main home or 900 square feet, whichever is smaller (M.G.L. c.40A §1A and 760 CMR 71.02). State guidance counts basements, lofts and other floored levels in gross floor area. Some towns, including Newton, allow larger ADUs under their own rules.",
 ["mgl1a","760cmr"],
 [("The state cap",[F("The statutory definition caps ADU gross floor area at half the principal dwelling's gross floor area or 900 sq ft, whichever is smaller.","mgl1a"),
   F("The state regulation repeats the same smaller-of-half-or-900-square-feet limit.","760cmr"),
   F("State guidance says gross floor area includes basements, lofts and intermediate floored levels, and it lists some spaces that are excluded.","adu-faq")]),
  ("Newton's local limits",[F("Newton's baseline for both internal and detached ADUs is 1,000 sq ft or 50% of the principal dwelling's gross floor area, whichever is less. A special permit can allow up to 1,200 sq ft for internal ADUs and 1,500 sq ft for detached ADUs (Ord. Sec. 6.7.1.D–E).","ord")])],
 [Q("What is the maximum ADU size under Massachusetts law?","The smaller of half the main home's gross floor area or 900 square feet.","mgl1a"),
  Q("Does my basement count toward gross floor area?","State guidance says gross floor area includes basements, lofts and intermediate floored levels.","adu-faq"),
  Q("Can a Newton ADU be bigger than 900 sq ft?","Newton's ordinance sets a 1,000 sq ft / 50% baseline, with larger sizes by special permit (Sec. 6.7.1).","ord")],
 ["How gross floor area is measured for your specific house."],"adu-state",
 ["are-adus-allowed-in-massachusetts","newton-adu-rules","newton-floor-area-ratio-far"])

g("newton-adu-rules","ADUs","ADUs","What are the ADU rules in Newton, MA?","Newton ADU Rules: Size, Parking, Rentals and Permits",
 "Newton accessory dwelling unit rules from Ord. Sec. 6.7.1: one per lot, no extra parking, 30-day minimum rentals, and size limits for internal and detached ADUs.",
 "Newton allows one ADU per lot on a single- or two-family property, in any zoning district. No extra parking is required, the ADU can't be sold separately, and rentals must be at least 30 days. The baseline size is 1,000 sq ft or 50% of the home's floor area, whichever is less, and a special permit can allow more.",
 ["newton-adu","ord"],
 [("Core rules (Ord. Sec. 6.7.1)",[F("A single- or two-family home may add one ADU regardless of zoning district, according to Newton Planning.","newton-adu"),
   F("No more than one ADU per lot, and no separate ownership (Sec. 6.7.1.C.1–2).","ord"),F("No additional parking is required (Sec. 6.7.1.C.5).","ord"),
   F("Minimum rental or occupancy term of 30 days for either dwelling (Sec. 6.7.1.C.4).","ord")]),
  ("Size",[F("Internal ADU: up to 1,000 sq ft or 50% of the total gross floor area, whichever is less. The total counts both units (Sec. 6.7.1.D.2).","ord"),
   F("Internal ADU by special permit: up to 1,200 sq ft (Sec. 6.7.1.D.2.b).","ord"),
   F("Newton Planning describes a conditional by-right allowance for internal ADUs of up to the smaller of 1,200 sq ft or 50%, for a residence whose certificate of occupancy is at least four years old.","newton-adu"),
   F("Detached ADU: up to 1,000 sq ft or 50%, whichever is less, or up to 1,500 sq ft by special permit (Sec. 6.7.1.E.2).","ord")])],
 [Q("Can I build an ADU in Newton?","Newton Planning says a single- or two-family home may add one ADU regardless of zoning district.","newton-adu"),
  Q("Do I need extra parking for a Newton ADU?","No. Sec. 6.7.1.C.5 requires no additional parking.","ord"),
  Q("Can I Airbnb my ADU in Newton?","The ordinance sets a minimum rental or occupancy term of 30 days (Sec. 6.7.1.C.4).","ord"),
  Q("How big can a detached ADU be in Newton?","1,000 sq ft or 50% of the total gross floor area, whichever is less, or up to 1,500 sq ft by special permit.","ord"),
  Q("Can I sell the ADU separately?","No. The ordinance prohibits separate ownership (Sec. 6.7.1.C.1).","ord"),
  Q("Who answers ADU questions in Newton?","Newton Planning lists an ADU questions email (adu@newtonma.gov) on its ADU page.","newton-adu")],
 ["Whether your house meets the four-year certificate-of-occupancy condition.","Setbacks and design rules for detached ADUs."],"newton-adu",
 ["are-adus-allowed-in-massachusetts","how-big-can-an-adu-be-in-massachusetts","newton-special-permits-and-variances"])

